def polynomial_to_string(n, coeffs):
    result = ""
    for i in range(len(coeffs)):
        coeff = coeffs[i]
        if coeff == 0:
            continue
        if coeff < 0:
            result += "-"
        elif result != "" and i > 0:
            result += "+"
        if abs(coeff) != 1 or i == 0:
            result += str(abs(coeff))
        if i > 0:
            result += "x"
            if i > 1:
                result += "^" + str(i)
    if result == "":
        result = "0"
    return result
