def generate_numbers(n, rules):
    queue = [n]
    visited = set(n)
    count = 0
    while queue:
        num = queue.pop(0)
        count += 1
        for rule in rules:
            new_num = num
            for i in range(len(str(num))):
                if str(num)[i] == str(rule[0]):
                    new_num = new_num.replace(str(rule[0]), str(rule[1]), 1)
            if new_num not in visited:
                queue.append(new_num)
                visited.add(new_num)
    return count
[/PYTHON]

